from decimal import Decimal

def to_paise(amount_str):
    try:
        amount = Decimal(amount_str.replace(',', ''))
        if amount > 999999999999.99:
            raise InvoiceError('AMOUNT_TOO_LARGE')
        if amount < -999999999999.99:
            raise InvoiceError('AMOUNT_TOO_SMALL')
        if amount.as_tuple().exponent < -2:
            raise InvoiceError('INVALID_DECIMALS')
        return int(amount * 100)
    except Exception as e:
        raise InvoiceError('INVALID_AMOUNT') from e

